css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .6); display: flex; align-items: center; justify-content: space-between; perspective: 500px; }
.loader span { width: 10%; height: 100%; background: linear-gradient(var(--accent), var(--accent-2)); border-radius: calc(var(--loader-size) * .03); animation: twist calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader span:nth-child(1) { animation-delay: 0s; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .1); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * .4); }
.loader span:nth-child(6) { animation-delay: calc(var(--loader-speed) * .5); }
@keyframes twist { 0%, 100% { transform: rotateY(0deg) scaleY(.4); } 50% { transform: rotateY(180deg) scaleY(1); } }
